/**
 * Save the Plumber's campaign: eight worlds of four, from Bluebell Pipeworks to
 * the Stardrain Citadel, built for height. The heroine moves freely, and a
 * seeded generator stacks each leg with climbs: terraces, towers with ledges up
 * their faces, pits crossed on staggered blocks, lifts, pistons and bridges,
 * springsteps up tall walls, and split routes with a corridor below and a high
 * road above. Each leg's Golden Gear sits on a harder route each world.
 * Tiles are 16px; legs are 24 rows tall with the lowest ground on row 21.
 * verifySavePlumberLevels.test.ts plays every leg through, and
 * verifySavePlumberGears.test.ts proves every gear can be reached.
 *
 *   .  empty          #  ground           B  block           =  one-way ledge
 *   g  valve gate     v  valve switch     o  brass token     c  wooden crate
 *   p  pumpbug        r  rivet roller     ^  steam vent      s  springstep
 *   P  piston (rises and falls)           L  brass lift (slides side to side)
 *   K  checkpoint     G  goal valve       D  pipe door       E  secret-room pipe
 *   @  start          X  boss gate        M  the world's boss
 *   f  slippery ice   b  breakable snowbank   d  fragile ice   e  falling icicle   q  rolling snowball
 *   w  water          F  bobbing raft     m  clockwork minnow (leaps from water)
 *   k  cork crab      u  glass gull       l  moss lantern     h  spring hare
 *   <  belt carrying left                 >  belt carrying right
 *   j  gasket golem   y  paper kite       n  umbrella mite
 *   ~  wind corridor (the whole column gusts a headwind)
 *   Q  cargo drop (crates fall here and rest a moment as steps)
 *   :  crystal bridge (solid only while it glows)
 *   |  rope ladder (up or down grabs it, A hops off; stand on its top rung)
 *   / and \\  walkable uphill and downhill ramps
 *   0  brass key (she carries one at a time; a hit sends it home)
 *   [  padlocked bolt (a wall; touch it holding a key to open the whole bolt)
 *   i  puddle mimic   z  siphon sprite    t  chimney spirit   T  tea-kettle knight
 *   1  Springstep power   2  Bottled Storm power   3  Pocket Lift power
 *   4  Sailwing power (hold jump during descent to glide)
 *   5  Ballast Boots power (heavy: headwinds and gales cannot push her)
 *   6  Tidecoat power (swim with Up/Jump, dive with Down)
 *   +  water heart (restores a heart)
 *   *  the stage's Golden Gear (one per stage, harder to reach each world)
 *   !  a glider: flies at her at head height (duck under it, swing or stomp)
 *   ?  gravity well (space course): draws the heroine toward its center
 *   %  compressed-air canister: restores jet pressure in space
 *   ;  recharge dock: continuously tops up pressure when nearby
 *   &  orbiting space debris: circles its anchor and hurts on contact
 *   _  scale plate: weighed down by Ballast Boots or a parked Gurgle
 *   Z  sluice gate (a wall that lifts while every scale plate is weighed down)
 *   $  solar gust: pulses outward after a visible warning
 */

export const TILE = 16

export type MazeRoom = {
  name: string
  /** First column of a 24-tile room, with two doors and a central arrival. */
  col: number
  drip: 'left' | 'right'
}

export type WildwaterDef = {
  name: string
  tap: { col: number; row: number }
  pearl: { col: number; row: number }
  steps: { row: number; from: number; to: number }[]
  bloomPistons?: boolean
}

export type StageDef = {
  code: string
  name: string
  rows: string[]
  secretExit?: { col: number; row: number }
  gurgleBarrel?: { col: number; row: number }
  wildwater?: WildwaterDef
  /** Connected Hush House rooms; their rising drips identify the forward door. */
  mazeRooms?: readonly MazeRoom[]
  /** A forced-scroll stretch, in tile columns, with speed in pixels per tick. */
  autoScroll?: { from: number; to: number; speed: number }
  /** Optional solid steps powered by a cleared Valve Chapel. */
  switchBlocks?: { chapel: string; row: number; from: number; to: number }[]
  /** Unlit: only the heroine and moss lanterns cast light. */
  dark?: boolean
  snow?: boolean
  /** Optional zero-gravity jetpack course, never applied to campaign stages. */
  space?: boolean
}

